pub fn scoped_pointer_input(message: &Message) -> bool {
    match &message.union {
        Some(message::Union::MouseEvent(_)) => true,
        Some(message::Union::PointerDeviceEvent(event)) => matches!(&event.union,
            Some(pointer_device_event::Union::TouchEvent(touch)) if matches!(&touch.union,
                Some(touch_event::Union::ScaleUpdate(_)))),
        _ => false,
    }
}

fn persistent_key(event: &KeyEvent) -> bool {
    match &event.union {
        Some(key_event::Union::ControlKey(key)) => !matches!(key.enum_value_or_default(),
            ControlKey::CtrlAltDel | ControlKey::LockScreen),
        Some(key_event::Union::Chr(_)) | Some(key_event::Union::Win2winHotkey(_)) => true,
        _ => false,
    }
}

fn same_key(left: &KeyEvent, right: &KeyEvent) -> bool {
    if left.mode != right.mode { return false; }
    match (&left.union, &right.union) {
        (Some(key_event::Union::Win2winHotkey(a)), Some(key_event::Union::Win2winHotkey(b))) =>
            a >> 16 == b >> 16,
        (a, b) => a == b,
    }
}

fn release(event: &KeyEvent) -> KeyEvent {
    let mut event = event.clone();
    event.down = false;
    event.press = false;
    event.modifiers.clear();
    // The low word represents text on down, not part of the physical VK on up.
    if let Some(key_event::Union::Win2winHotkey(code)) = event.union {
        event.set_win2win_hotkey(code & 0xffff0000);
    }
    event
}

// Older Windows receivers release Control on Scale0. Reapply only this connection's
// still-owned post-swap Control identities. Raw Map avoids Legacy's temporary
// modifiers and Win2winHotkey's Unicode-first Down, preserving other held keys.
fn windows_control_replay(event: &KeyEvent) -> Option<KeyEvent> {
    use hbb_common::message_proto::KeyboardMode;
    let mode = event.mode.enum_value_or_default();
    let scan = match (&event.union, mode) {
        (Some(key_event::Union::ControlKey(key)), KeyboardMode::Legacy | KeyboardMode::Auto) => match key.enum_value().ok()? {
            ControlKey::Control => 0x1D,
            ControlKey::RControl => 0xE01D,
            _ => return None,
        },
        (Some(key_event::Union::Chr(code)), KeyboardMode::Map) if matches!(*code, 0x1D | 0xE01D) => *code,
        (Some(key_event::Union::Chr(code)), KeyboardMode::Translate) => match code >> 16 {
            0 if matches!(*code, 0x1D | 0xE01D) => *code,
            0x11 | 0xA2 => 0x1D,
            0xA3 => 0xE01D,
            _ => return None,
        },
        (Some(key_event::Union::Win2winHotkey(code)), KeyboardMode::Translate) => match code >> 16 {
            0x11 | 0xA2 => 0x1D,
            0xA3 => 0xE01D,
            _ => return None,
        },
        _ => return None,
    };
    let mut replay = event.clone();
    replay.mode = KeyboardMode::Map.into();
    replay.set_chr(scan);
    replay.down = true;
    replay.press = false;
    replay.modifiers.clear();
    Some(replay)
}

